<div class="card shadow-sm mb-4"><div class="card-header"><h2 class="card-title mb-0">Rate History</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Schedule</th><th>Basic Daily</th><th>Basic Monthly</th><th>OT (2 hrs)</th><th>Daily Rate</th><th>Before Admin</th><th>Total Rate</th><th>Status</th><th>Current</th><th>Recorded</th></tr></thead><tbody><?php foreach ($rates as $rate): ?><tr><td><?= html_escape($rate->schedule_code ?? '—') ?></td><td><?= number_format($rate->basic_daily_rate, 2) ?></td><td><?= number_format($rate->basic_monthly_rate, 2) ?></td><td><?= number_format($rate->ot_rate_2hrs, 2) ?></td><td><?= number_format($rate->daily_rate, 2) ?></td><td><?= number_format($rate->total_without_admin_fee, 2) ?></td><td><?= html_escape(($rate->currency_code ? $rate->currency_code.' ' : '').number_format($rate->total_with_admin_fee, 2)) ?></td><td><?= html_escape($rate->rate_status ?? '—') ?></td><td><?= $rate->is_current ? 'Yes' : 'No' ?></td><td><?= html_escape(date('d-M-Y h:i A', strtotime($rate->created_at))) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="card shadow-sm mb-4"><div class="card-header"><h2 class="card-title mb-0">Rate Components</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Code</th><th>Component</th><th>Category</th><th>Basis</th><th>Amount</th><th>Source Value</th><th>Current Rate</th></tr></thead><tbody><?php foreach ($components as $component): ?><tr><td><?= html_escape($component->component_code) ?></td><td><?= html_escape($component->component_name) ?></td><td><?= html_escape($component->component_category ?? '—') ?></td><td><?= html_escape($component->amount_basis ?? '—') ?></td><td><?= html_escape(($component->currency_code ? $component->currency_code.' ' : '').number_format($component->amount, 2)) ?></td><td><?= html_escape($component->source_value_text ?? '—') ?></td><td><?= $component->is_current ? 'Yes' : 'No' ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="row g-4"><div class="col-xl-5"><div class="card shadow-sm h-100"><div class="card-header"><h2 class="card-title mb-0">Source Aliases</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Source</th><th>Labor Name</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach ($aliases as $alias): ?><tr><td><?= html_escape($alias->source_system) ?></td><td><?= html_escape($alias->source_labor_name) ?></td><td><?= $alias->is_active ? 'Active' : 'Inactive' ?></td><td><?= html_escape($alias->mapping_notes ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
	<div class="col-xl-7"><div class="card shadow-sm h-100"><div class="card-header"><h2 class="card-title mb-0">Standard Cost Item Usage</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Cost Code</th><th>Standard Item</th><th>Revision</th><th>Crew Qty.</th><th>Days / Item Unit</th><th>Hours / Unit</th><th>Status</th></tr></thead><tbody><?php foreach ($usages as $usage): ?><tr><td><?= html_escape($usage->enterprise_cost_code ?? '—') ?></td><td><?= html_escape($usage->standard_item_name) ?></td><td><?= html_escape($usage->revision_no) ?></td><td><?= $usage->crew_quantity !== NULL ? number_format($usage->crew_quantity, 4) : '—' ?></td><td><?= $usage->labor_days_per_item_unit !== NULL ? number_format($usage->labor_days_per_item_unit, 6) : '—' ?></td><td><?= $usage->labor_hours_per_unit !== NULL ? number_format($usage->labor_hours_per_unit, 6) : '—' ?></td><td><?= html_escape($usage->revision_status ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div>
